105:   if (nameMatch && !memory.name) memory.name = nameMatch[1].trim().slice(0, 32);
106:   const matched = rules.find((rule) => rule.keys.some((key) => lower.includes(key)));
107:   let reply, emotion = 'внимание';
108:   if (matched) {
