110:     if (!memory.likes.includes(matched.topic)) memory.likes.push(matched.topic);
111:   } else if (/[?？]$/.test(text) || lower.startsWith('почему') || lower.startsWith('как ')) {
112:     reply = currentCharacter === 'mira' ? 'Хороший вопрос. Мне кажется, ответ иногда появляется, если не торопить его. А ты сам к чему склоняешься?' : 'Я не уверен, что есть один ответ. Что тебе самому кажется самым важным здесь?';
113:     emotion = 'слушает';
114:   } else if (/люблю|нравится/.test(lower)) {
115:     reply = currentCharacter === 'mira' ? 'Запомню. Мне нравится узнавать, какие вещи делают твой день теплее.' : 'Я это запомню. Такие детали здорово помогают почувствовать человека.';
116:   } else {
