*{box-sizing:border-box}
 :root{font-family:'DM Sans',sans-serif;color:#443a3a;font-synthesis:none}
html,body,#game{margin:0;width:100%;height:100%;overflow:hidden;background:#e8d8d1}
body{touch-action:none}
button,input,select{font:inherit}
button{color:inherit}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(34,28,30,.24),transparent 25%,transparent 68%,rgba(38,28,29,.28)),linear-gradient(90deg,rgba(42,27,31,.1),transparent 35%,transparent 75%,rgba(42,27,31,.08))}
.topbar{position:absolute;z-index:2;top:max(22px,env(safe-area-inset-top));left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;color:#fff;text-shadow:0 1px 10px #423b4070}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{display:grid;place-items:center;width:39px;height:39px;border-radius:14px;background:#fff2;color:#fff;font-size:21px;border:1px solid #ffffff50;backdrop-filter:blur(12px)}
.brand b{font:700 14px Manrope,sans-serif;letter-spacing:.01em;display:block}
.brand small{font-size:11px;opacity:.78;display:block;margin-top:3px}
.top-actions{display:flex;gap:9px}
.icon-btn{height:42px;width:42px;border-radius:14px;border:1px solid #ffffff55;background:#fff2;color:white;font-size:19px;backdrop-filter:blur(12px);cursor:pointer}
.scene-label{position:absolute;left:34px;top:104px;color:#fff;letter-spacing:.16em;font-size:9px;font-weight:700;text-shadow:0 1px 8px #362c2c}
.live-dot,.mood-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c9e8c1;margin-right:8px;box-shadow:0 0 9px #aee3a0}
.label-sep{margin:0 11px;opacity:.65}
.companion-chip{position:absolute;right:34px;top:96px;display:flex;align-items:center;gap:10px;padding:8px 11px 8px 8px;border:1px solid #ffffff60;background:#fffdf1c9;border-radius:16px;box-shadow:0 8px 28px #46363224;backdrop-filter:blur(16px);min-width:166px}
.avatar,.dialog-avatar{display:grid;place-items:center;border-radius:12px;color:#fff;background:linear-gradient(145deg,#c88385,#72506f);font:700 17px Manrope}
.avatar{height:38px;width:38px}
.companion-chip strong{font:700 13px Manrope;display:block}
.companion-chip small{display:block;color:#8a7774;font-size:10px;margin-top:4px}
.mood-dot{background:#a9c399;width:5px;height:5px;margin-right:5px}
.swap{margin-left:auto;border:0;background:transparent;color:#9c7774;font-size:19px;cursor:pointer}
.focus-hint{position:absolute;top:46%;left:50%;transform:translate(-50%,-50%);border:1px solid #ffffff50;color:#fff;padding:10px 15px;border-radius:999px;background:#3d313136;backdrop-filter:blur(9px);font-size:11px;opacity:.88;white-space:nowrap;cursor:pointer}
.focus-hint b{font-weight:500;opacity:.8}
.focus-hint i{font-style:normal;padding-left:9px}
.look-note{position:absolute;bottom:158px;left:50%;transform:translateX(-50%);color:#fff;font-size:10px;letter-spacing:.035em;text-shadow:0 1px 6px #382e2e;opacity:.77}
.conversation{position:absolute;z-index:3;left:50%;bottom:132px;width:min(590px,calc(100% - 38px));transform:translate(-50%,18px);opacity:0;pointer-events:none;transition:opacity .28s,transform .28s}
.conversation.open{opacity:1;transform:translate(-50%,0);pointer-events:auto}
.dialog-card{padding:17px 19px 12px;border:1px solid #fff9;border-radius:18px;background:rgba(255,251,245,.94);box-shadow:0 14px 40px #49363830;backdrop-filter:blur(18px)}
.dialog-top{display:flex;align-items:center;gap:11px}
.dialog-avatar{height:40px;width:40px;border-radius:13px;font-size:17px}
.dialog-meta{flex:1}
.dialog-meta strong{font:700 13px Manrope;color:#614854}
.dialog-meta span{font-size:11px;color:#b4868c;margin-left:5px}
.dialog-caption{font-size:10px;color:#a59891;margin-top:4px}
.close-dialog,.close-settings{border:0;background:none;color:#9c8b87;font-size:23px;cursor:pointer}
.dialog-card p{font-size:14px;line-height:1.55;color:#514547;margin:14px 3px 8px}
.dialog-bottom{display:flex;justify-content:space-between;align-items:center;color:#ab9a94;font-size:10px}
.speak-reply{border:0;background:#f4e4e0;color:#a47378;border-radius:10px;height:29px;padding:0 10px;cursor:pointer}
.quick-actions{display:flex;justify-content:center;gap:8px;margin-top:9px;overflow:auto;scrollbar-width:none}
.quick-actions button{white-space:nowrap;border:1px solid #fff9;background:#fffdf0db;border-radius:11px;padding:9px 13px;color:#a47477;font-size:13px;box-shadow:0 4px 15px #42333316;cursor:pointer}
.quick-actions span{font-size:10px;color:#6b5b59;margin-left:3px}
.controls{position:absolute;z-index:2;bottom:max(28px,env(safe-area-inset-bottom));left:32px;right:32px;display:flex;align-items:end;justify-content:space-between;color:#fff}
.move-control{display:flex;align-items:center;gap:10px;font-size:9px;letter-spacing:.06em;text-shadow:0 1px 5px #342a2b}
.joystick{width:93px;height:93px;position:relative;display:grid;place-items:center}
.joy-ring{position:absolute;inset:0;border-radius:50%;border:1px solid #ffffff75;background:#ffffff20;backdrop-filter:blur(6px)}
.stick{width:38px;height:38px;border-radius:50%;background:#fff9;border:1px solid #ffffffab;box-shadow:0 3px 10px #382a2a27;position:relative;z-index:1}
.center-controls{display:flex;gap:13px;align-items:end;position:absolute;left:50%;transform:translateX(-50%);bottom:0}
.round-control{border:1px solid #ffffff60;background:#fff2;backdrop-filter:blur(10px);color:white;border-radius:16px;width:57px;height:57px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;cursor:pointer}
.round-control span{font-size:19px}
.round-control small{font-size:9px;opacity:.83}
.round-control.active{background:#fff4}
.action-control{border:1px solid #ffffffac;background:#fffdf0e8;color:#8e6269;border-radius:18px;width:77px;height:77px;box-shadow:0 7px 25px #382b2b26;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;cursor:pointer}
.action-control span{font-size:24px}
.action-control small{font-size:9px;font-weight:600}
.composer{position:absolute;z-index:4;bottom:122px;left:50%;transform:translate(-50%,12px);width:min(510px,calc(100% - 40px));border:1px solid #fff;background:#fffdf3f2;border-radius:15px;box-shadow:0 10px 34px #30252630;display:flex;padding:5px;opacity:0;pointer-events:none;transition:.2s}
.composer.open{opacity:1;pointer-events:auto;transform:translate(-50%,0)}
.composer input{border:0;outline:0;background:transparent;padding:10px 12px;flex:1;min-width:0;color:#534749;font-size:13px}
.composer input::placeholder{color:#aa9a97}
.composer button{width:38px;border:0;background:#b57e82;color:white;border-radius:11px;font-size:20px;cursor:pointer}
.toast{position:absolute;z-index:7;top:75px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.25s;border-radius:12px;padding:10px 15px;color:#635456;background:#fffdf2e8;box-shadow:0 8px 22px #32292b24;font-size:12px;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.modal-backdrop{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:#30272a65;backdrop-filter:blur(5px);opacity:0;pointer-events:none;transition:.2s}
.modal-backdrop.open{opacity:1;pointer-events:auto}
.settings-card{position:relative;width:min(410px,calc(100% - 34px));border-radius:24px;background:#fffaf2;padding:30px;box-shadow:0 25px 80px #21191b50}
.close-settings{position:absolute;right:20px;top:15px}
.settings-kicker,.intro-overline{font-size:9px;font-weight:700;letter-spacing:.2em;color:#bb8587}
.settings-card h2{font:800 24px Manrope;margin:11px 0 6px;color:#5a4449}
.settings-card>p{font-size:12px;color:#a18f8b;margin:0 0 21px}
.setting-row{display:flex;align-items:center;justify-content:space-between;padding:15px 0;border-top:1px solid #eee4dc}
.setting-row b{display:block;font:700 12px Manrope;color:#665457}
.setting-row small{display:block;font-size:10px;color:#a69590;margin-top:4px}
.toggle{width:39px;height:23px;border:0;border-radius:99px;background:#ddd;position:relative;cursor:pointer}
.toggle:after{content:'';position:absolute;left:3px;top:3px;width:17px;height:17px;border-radius:50%;background:white;transition:.2s;box-shadow:0 2px 4px #0002}
.toggle.on{background:#c08a8c}
.toggle.on:after{left:19px}
.setting-row select{border:1px solid #e9d8d4;border-radius:9px;padding:8px 24px 8px 9px;color:#735e60;background:#fffaf5;font-size:11px}
.reset-memory{width:100%;margin-top:14px;border:1px solid #e6d5d0;background:transparent;color:#916d70;padding:11px;border-radius:12px;font-size:11px;cursor:pointer}
.privacy-note{font-size:9px;line-height:1.5;color:#aa9b94;margin-top:14px}
.intro{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(43,31,34,.58),rgba(50,36,37,.1) 78%);transition:opacity .7s,visibility .7s}
.intro.hidden{opacity:0;visibility:hidden;pointer-events:none}
.intro-card{margin-left:-30%;width:310px;color:white;text-shadow:0 2px 15px #31292a40}
.intro-star{font-size:28px;color:#f8ddd0}
.intro-overline{color:#f2d5cb;margin-top:20px}
.intro h1{font:600 45px/1.12 Manrope;letter-spacing:-.05em;margin:15px 0}
.intro h1 em{font-style:normal;color:#f1c5ba}
.intro-card p{font-size:13px;line-height:1.7;max-width:275px;color:#fffdf0d9}
.intro-card>button{margin-top:19px;border:0;background:#f9eee2;color:#77595a;border-radius:13px;padding:14px 17px;font-size:12px;font-weight:700;cursor:pointer;box-shadow:0 8px 22px #30242545}
.intro-card>button span{margin-left:20px}
.intro-card>small{display:block;color:#fffbf0a8;font-size:9px;margin-top:14px}
.intro-card{animation:arrive 1s .1s both}
@keyframes arrive{from{opacity:0;transform:translateY(12px)}
to{opacity:1;transform:translateY(0)}
}

@media(max-width:640px){.topbar{top:max(15px,env(safe-area-inset-top));left:16px;right:16px}
.brand-mark{width:34px;height:34px;border-radius:12px}
.brand b{font-size:12px}
.brand small{font-size:9px}
.icon-btn{width:37px;height:37px;border-radius:12px}
.scene-label{left:18px;top:77px;font-size:8px}
.companion-chip{right:15px;top:73px;min-width:146px;padding:6px 8px}
.avatar{height:33px;width:33px}
.focus-hint{top:43%;font-size:9px}
.look-note{bottom:134px;font-size:9px}
.controls{left:15px;right:15px;bottom:max(16px,env(safe-area-inset-bottom))}
.joystick{width:75px;height:75px}
.stick{width:33px;height:33px}
.move-control{font-size:8px;gap:6px}
.center-controls{gap:7px}
.round-control{width:48px;height:49px;border-radius:14px}
.round-control span{font-size:16px}
.round-control small{font-size:8px}
.action-control{width:65px;height:65px;border-radius:16px}
.conversation{bottom:105px;width:calc(100% - 24px)}
.dialog-card{padding:13px 14px 10px;border-radius:16px}
.dialog-card p{font-size:12px;margin:10px 2px 7px}
.dialog-avatar{width:35px;height:35px}
.dialog-caption{font-size:9px}
.quick-actions{justify-content:flex-start}
.quick-actions button{padding:8px 10px}
.composer{bottom:102px}
.intro-card{margin-left:0;width:min(300px,calc(100% - 52px));transform:translateY(8vh)}
.intro h1{font-size:42px}
.intro{background:linear-gradient(90deg,rgba(43,31,34,.52),rgba(50,36,37,.08))}
.settings-card{padding:26px 23px}
}

